import{_ as t,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Приложение - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":4,"title":"Привязка к контейнеру","slug":"привязка-к-контеинеру","link":"#привязка-к-контеинеру","children":[]},{"level":4,"title":"Разрешение из контейнера","slug":"разрешение-из-контеинера","link":"#разрешение-из-контеинера","children":[]},{"level":4,"title":"Привязка «общего» типа к контейнеру","slug":"привязка-«общего»-типа-к-контеинеру","link":"#привязка-«общего»-типа-к-контеинеру","children":[]},{"level":4,"title":"Привязка существующего экземпляра к контейнеру","slug":"привязка-существующего-экземпляра-к-контеинеру","link":"#привязка-существующего-экземпляра-к-контеинеру","children":[]},{"level":4,"title":"Привязка интерфейса к реализации","slug":"привязка-интерфеиса-к-реализации","link":"#привязка-интерфеиса-к-реализации","children":[]},{"level":3,"title":"Где регистрировать привязки","slug":"где-регистрировать-привязки","link":"#где-регистрировать-привязки","children":[]},{"level":2,"title":"Поставщики сервисов","slug":"поставщики-сервисов","link":"#поставщики-сервисов","children":[{"level":4,"title":"Определение поставщика сервиса","slug":"определение-поставщика-сервиса","link":"#определение-поставщика-сервиса","children":[]},{"level":4,"title":"Регистрация поставщика сервиса во время выполнения","slug":"регистрация-поставщика-сервиса-во-время-выполнения","link":"#регистрация-поставщика-сервиса-во-время-выполнения","children":[]}]},{"level":2,"title":"События приложения","slug":"события-приложения","link":"#события-приложения","children":[{"level":4,"title":"События запроса","slug":"события-запроса","link":"#события-запроса","children":[]},{"level":4,"title":"События контейнера","slug":"события-контеинера","link":"#события-контеинера","children":[]}]},{"level":2,"title":"Вспомогательные методы приложения","slug":"вспомогательные-методы-приложения","link":"#вспомогательные-методы-приложения","children":[{"level":4,"title":"Определение окружения приложения","slug":"определение-окружения-приложения","link":"#определение-окружения-приложения","children":[]},{"level":4,"title":"Определение контекста выполнения","slug":"определение-контекста-выполнения","link":"#определение-контекста-выполнения","children":[]}]}],"relativePath":"3.x/ru/extend/services/application.md","filePath":"3.x/ru/extend/services/application.md"}'),r={name:"3.x/ru/extend/services/application.md"};function u(k,n,d,h,g,v){const e=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(e),n[0]||(n[0]=l("h1",null,"Приложение",-1)),a(p),n[1]||(n[1]=i(`<p>Контейнер инверсии управления (IoC) — это инструмент для управления зависимостями классов. Внедрение зависимостей — это метод устранения жёстко закодированных зависимостей классов. Вместо этого зависимости внедряются во время выполнения, что обеспечивает большую гибкость, поскольку реализации зависимостей можно легко заменять.</p><h4 id="привязка-к-контеинеру"><a href="#привязка-к-контеинеру" class="header-anchor">#</a> Привязка к контейнеру</h4><p>Существует два способа разрешения зависимостей контейнером IoC: через callback-функции Closure и автоматическое разрешение. Сначала рассмотрим callback-функции Closure. Сначала «тип» может быть привязан к контейнеру.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">FooBar</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="разрешение-из-контеинера"><a href="#разрешение-из-контеинера" class="header-anchor">#</a> Разрешение из контейнера</h4><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Когда вызывается метод <code>App::make</code>, выполняется callback-функция Closure и возвращается результат.</p><h4 id="привязка-«общего»-типа-к-контеинеру"><a href="#привязка-«общего»-типа-к-контеинеру" class="header-anchor">#</a> Привязка «общего» типа к контейнеру</h4><p>Иногда вы можете захотеть привязать что-то к контейнеру, что должно быть разрешено только один раз, и тот же экземпляр должен возвращаться при последующих вызовах контейнера:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">singleton</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">FooBar</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="привязка-существующего-экземпляра-к-контеинеру"><a href="#привязка-существующего-экземпляра-к-контеинеру" class="header-anchor">#</a> Привязка существующего экземпляра к контейнеру</h4><p>Вы также можете привязать существующий экземпляр объекта к контейнеру с помощью метода <code>instance</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$foo</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Foo</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token variable">$foo</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="привязка-интерфеиса-к-реализации"><a href="#привязка-интерфеиса-к-реализации" class="header-anchor">#</a> Привязка интерфейса к реализации</h4><p>В некоторых случаях класс может зависеть от реализации интерфейса, а не от «конкретного типа». В этом случае необходимо использовать метод <code>App::bind</code>, чтобы сообщить контейнеру, какую реализацию интерфейса следует внедрить:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserRepositoryInterface&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;DbUserRepository&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Теперь рассмотрим следующий код:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserRepositoryInterface&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Поскольку мы привязали <code>UserRepositoryInterface</code> к конкретному типу, <code>DbUserRepository</code> будет автоматически внедрён в этот контроллер при его создании.</p><h3 id="где-регистрировать-привязки"><a href="#где-регистрировать-привязки" class="header-anchor">#</a> Где регистрировать привязки</h3><p>Привязки IoC, как и <a href="./event.html">обработчики событий</a>, обычно относятся к категории «загрузочного кода». Другими словами, они подготавливают ваше приложение к обработке запросов и обычно должны выполняться до фактического вызова маршрута или контроллера. Наиболее распространённое место — метод <code>boot</code> <a href="./../extending.html">файла регистрации плагина</a>. Альтернативно плагины могут предоставить файл с именем <strong>init.php</strong> в директории плагина, который вы можете использовать для размещения логики регистрации IoC.</p><h2 id="поставщики-сервисов"><a href="#поставщики-сервисов" class="header-anchor">#</a> Поставщики сервисов</h2><p>Поставщики сервисов — это отличный способ создания библиотек и выполнения связанных регистраций IoC в одном месте. В поставщике сервиса вы можете зарегистрировать пользовательский драйвер аутентификации, зарегистрировать классы репозиториев вашего приложения в контейнере IoC или даже настроить пользовательскую команду Artisan.</p><p>Фактически <a href="./../system/plugins.html">файлы регистрации плагинов</a> наследуют поставщики сервисов, и большинство основных компонентов включают поставщики сервисов. Все зарегистрированные поставщики сервисов для вашего приложения перечислены в массиве <code>providers</code> конфигурационного файла <code>config/app.php</code>.</p><h4 id="определение-поставщика-сервиса"><a href="#определение-поставщика-сервиса" class="header-anchor">#</a> Определение поставщика сервиса</h4><p>Для создания поставщика сервиса просто расширьте класс <code>October\\Rain\\Support\\ServiceProvider</code> и определите метод <code>register</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Support<span class="token punctuation">\\</span>ServiceProvider</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">FooServiceProvider</span> <span class="token keyword">extends</span> <span class="token class-name">ServiceProvider</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">app</span><span class="token operator">-&gt;</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Foo</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Обратите внимание, что в методе <code>register</code> контейнер IoC приложения доступен через свойство <code>$this-&gt;app</code>. После создания провайдера и готовности к его регистрации в вашем приложении просто добавьте его в массив <code>providers</code> в конфигурационном файле <code>app</code>.</p><h4 id="регистрация-поставщика-сервиса-во-время-выполнения"><a href="#регистрация-поставщика-сервиса-во-время-выполнения" class="header-anchor">#</a> Регистрация поставщика сервиса во время выполнения</h4><p>Вы также можете зарегистрировать поставщик сервиса во время выполнения с помощью метода <code>App::register</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FooServiceProvider&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="события-приложения"><a href="#события-приложения" class="header-anchor">#</a> События приложения</h2><h4 id="события-запроса"><a href="#события-запроса" class="header-anchor">#</a> События запроса</h4><p>Вы можете зарегистрировать специальные события перед маршрутизацией запроса с помощью методов <code>before</code> и <code>after</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Code to execute before the request is routed</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Code to execute after the request is routed</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="события-контеинера"><a href="#события-контеинера" class="header-anchor">#</a> События контейнера</h4><p>Сервис-контейнер генерирует событие каждый раз, когда он разрешает объект. Вы можете слушать это событие с помощью метода <code>resolving</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$object</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Called when container resolves object of any type...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$fooBar</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Called when container resolves objects using hint &quot;foo&quot;...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">resolving</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Acme\\Blog\\Classes\\FooBar&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$fooBar</span><span class="token punctuation">,</span> <span class="token variable">$app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Called when container resolves objects of type &quot;FooBar&quot;...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Как видите, разрешаемый объект передаётся в callback, позволяя вам установить любые дополнительные свойства объекта перед его передачей потребителю.</p><h2 id="вспомогательные-методы-приложения"><a href="#вспомогательные-методы-приложения" class="header-anchor">#</a> Вспомогательные методы приложения</h2><h4 id="определение-окружения-приложения"><a href="#определение-окружения-приложения" class="header-anchor">#</a> Определение окружения приложения</h4><p>Вы можете использовать метод <code>environment</code> для определения окружения приложения, как оно настроено в <a href="./../../setup/configuration.html">конфигурации окружения</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// production</span>
<span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">environment</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="определение-контекста-выполнения"><a href="#определение-контекста-выполнения" class="header-anchor">#</a> Определение контекста выполнения</h4><p>Можно узнать, выполняется ли текущий запрос в административной области панели управления, с помощью метода <code>runningInBackend</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">runningInBackend</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете использовать метод <code>runningInConsole</code>, чтобы проверить, выполняется ли код в <a href="./../console-commands.html">интерфейсе командной строки</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">runningInConsole</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,48))])}const x=t(r,[["render",u]]);export{m as __pageData,x as default};
